/* ============================ DICTIONARY / TOKENIZER ============================ */
const DICT = {};
// DICT entries are [pinyin, meaning, level]. level is additive (used by wordInfo()
// for the story-reader translation popup's HSK badge); existing callers that only
// read entry[0]/entry[1] (wireTokClicks' transbar) are unaffected.
VOCAB.forEach(v=>{ DICT[v[0]] = [v[1], v[2], v[3]]; });
EXTRA_WORDS.forEach(v=>{ if(!DICT[v[0]]) DICT[v[0]] = [v[1], v[2], v[3]]; });
HSK4_WORDS.forEach(v=>{ if(!DICT[v[0]]) DICT[v[0]] = [v[1], v[2], v[3]]; });
const DICT_MAXLEN = Math.max(...Object.keys(DICT).map(k=>k.length));
const CJK_RE = /[一-鿿]/;

// Looks up a hanzi word/phrase for the story-reader translation popup. Returns
// {word, pinyin, level, defs:[...]} with defs split on "; " into numbered entries,
// or null gracefully if the word isn't in DICT (VOCAB/EXTRA_WORDS/HSK4_WORDS) --
// callers must handle null by showing a "no definition found" message rather than
// throwing.
function wordInfo(word){
  const entry = DICT[word];
  if(!entry) return null;
  const defs = entry[1].split(/;\s*/).filter(Boolean);
  return { word, pinyin: entry[0], level: entry[2] || null, defs: defs.length ? defs : [entry[1]] };
}

function escapeHtml(s){
  return s.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
}

// Greedy longest-match tokenizer over DICT; returns HTML with clickable spans for
// recognized words. Punctuation and unrecognized characters pass through as plain text.
function tokenizeHanzi(text){
  let html = "";
  let i = 0;
  while(i < text.length){
    const ch = text[i];
    if(!CJK_RE.test(ch)){ html += escapeHtml(ch); i++; continue; }
    let matched = false;
    for(let len = Math.min(DICT_MAXLEN, text.length - i); len >= 1; len--){
      const seg = text.slice(i, i+len);
      if(DICT[seg]){
        html += `<span class="tok" data-word="${encodeURIComponent(seg)}">${escapeHtml(seg)}</span>`;
        i += len;
        matched = true;
        break;
      }
    }
    if(!matched){ html += escapeHtml(ch); i++; }
  }
  return html;
}

// Like tokenizeHanzi, but wraps every exact-substring occurrence of `boldWord`
// in <b> so the current flashcard's vocab word stands out within the example
// sentence. Falls back to plain tokenizeHanzi if boldWord is missing/empty or
// doesn't occur in the text (no error in that edge case).
function tokenizeHanziWithBold(text, boldWord){
  if(!boldWord){ return tokenizeHanzi(text); }
  let html = "";
  let i = 0;
  while(i < text.length){
    const idx = text.indexOf(boldWord, i);
    if(idx === -1){
      html += tokenizeHanzi(text.slice(i));
      break;
    }
    html += tokenizeHanzi(text.slice(i, idx));
    html += `<b>${tokenizeHanzi(text.slice(idx, idx + boldWord.length))}</b>`;
    i = idx + boldWord.length;
  }
  return html;
}

// Wires up click-to-translate on any container that has tokenized spans inside it,
// updating the translation bar with id `barId`.
function wireTokClicks(container, barId){
  container.querySelectorAll(".tok").forEach(span=>{
    span.onclick = ()=>{
      container.querySelectorAll(".tok.picked").forEach(s=>s.classList.remove("picked"));
      span.classList.add("picked");
      const word = decodeURIComponent(span.dataset.word);
      const entry = DICT[word];
      const bar = document.getElementById(barId);
      if(bar && entry){
        bar.innerHTML = `<span class="tb-zh">${word}</span><span class="tb-py">${entry[0]}</span><span>${entry[1]}</span>`;
      }
    };
  });
}

